ALTER TABLE public.profiles ADD COLUMN monere_points integer NOT NULL DEFAULT 0 CHECK (monere_points >= 0), ADD COLUMN monere_tokens integer NOT NULL DEFAULT 0 CHECK (monere_tokens >= 0), ADD COLUMN last_energy_claim_date date, ADD COLUMN subscription_tier text NOT NULL DEFAULT 'free' CHECK (subscription_tier IN ('free','monere_plus','monere_club'));
UPDATE public.profiles p SET monere_points=COALESCE((SELECT sum(points) FROM public.point_credits c WHERE c.user_id=p.user_id),0), monere_tokens=p.tokens, last_energy_claim_date=p.last_care_claim_date;
COMMENT ON COLUMN public.profiles.monere_points IS 'Verified account credits; shared wallet deducts existing local clothing, habitat and hint spending.';
COMMENT ON COLUMN public.profiles.tokens IS 'DEPRECATED compatibility mirror of monere_tokens.';
COMMENT ON COLUMN public.profiles.last_care_claim_date IS 'DEPRECATED compatibility mirror of last_energy_claim_date.';
CREATE OR REPLACE FUNCTION public.apply_point_credit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(user_id,monere_points) VALUES(NEW.user_id,NEW.points) ON CONFLICT(user_id) DO UPDATE SET monere_points=profiles.monere_points+NEW.points; RETURN NEW; END; $$;
CREATE TRIGGER point_credit_apply AFTER INSERT ON public.point_credits FOR EACH ROW EXECUTE FUNCTION public.apply_point_credit();
CREATE OR REPLACE FUNCTION public.apply_token_credit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(user_id,tokens,monere_tokens) VALUES(NEW.user_id,NEW.tokens,NEW.tokens) ON CONFLICT(user_id) DO UPDATE SET monere_tokens=profiles.monere_tokens+NEW.tokens,tokens=profiles.monere_tokens+NEW.tokens; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.account_tier(p_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM subscriptions WHERE user_id=p_user AND environment='live' AND product_id='club' AND ((status IN ('active','trialing','past_due') AND (current_period_end IS NULL OR current_period_end>now())) OR (status='canceled' AND current_period_end>now()))) THEN 'monere_club' WHEN EXISTS(SELECT 1 FROM subscriptions WHERE user_id=p_user AND environment='live' AND ((status IN ('active','trialing','past_due') AND (current_period_end IS NULL OR current_period_end>now())) OR (status='canceled' AND current_period_end>now()))) OR EXISTS(SELECT 1 FROM code_redemptions r JOIN organization_codes c ON c.id=r.code_id WHERE r.user_id=p_user AND c.is_active AND c.expiration_date>now()) THEN 'monere_plus' ELSE 'free' END; $$;
REVOKE ALL ON FUNCTION public.account_tier(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.project_subscription_tier() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(user_id,subscription_tier) VALUES(NEW.user_id,public.account_tier(NEW.user_id)) ON CONFLICT(user_id) DO UPDATE SET subscription_tier=public.account_tier(NEW.user_id); RETURN NEW; END; $$;
CREATE TRIGGER subscription_tier_project AFTER INSERT OR UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.project_subscription_tier();
CREATE TRIGGER code_tier_project AFTER INSERT ON public.code_redemptions FOR EACH ROW EXECUTE FUNCTION public.project_subscription_tier();
UPDATE public.profiles SET subscription_tier=public.account_tier(user_id);